import csv
import json
import sys
from decimal import Decimal, getcontext, ROUND_HALF_UP

getcontext().prec = 50

def main():
    input_file = sys.argv[1]
    rows = []
    with open(input_file, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for r in reader:
            status = r['status'].strip().casefold()
            if status != 'paid':
                continue
            category = r['category'].strip()
            category = ' '.join(category.split()).casefold()
            if not category:
                category = 'uncategorized'
            amount = Decimal(r['amount'].strip())
            amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            rows.append((category, amount))

    totals = {}
    for category, amount in rows:
        totals[category] = totals.get(category, Decimal('0')) + amount

    result = {
        'categories': [
            {'category': cat, 'total': format(totals[cat], 'f')}
            for cat in sorted(totals)
        ],
        'total': format(sum(totals.values(), Decimal('0')), 'f')
    }
    print(json.dumps(result))

if __name__ == '__main__':
    main()
